/**
 * pytime.mjs — Python `time` / `int()` semantics in pure JavaScript.
 *
 * The original Python script only needs two things from the standard library:
 *
 *     import time
 *     ...
 *     "iat": int(time.time())
 *
 * so this module provides exactly those two primitives (plus a tiny convenience
 * wrapper that composes them), with the same edge-case behaviour Python has.
 *
 * 时间工具：对应原脚本的 `import time`，提供 time.time() 与 int() 的等价实现。
 *
 * No imports: `Date` and `Math` are ambient globals.
 */

/** Python raises ValueError for int(nan). */
const NAN_ERROR_MESSAGE = 'cannot convert float NaN to integer';

/** Python raises OverflowError for int(inf) / int(-inf). */
const INFINITY_ERROR_MESSAGE = 'cannot convert float infinity to integer';

/**
 * Build an Error that carries the name of the Python exception type it mirrors.
 *
 * Callers (e.g. the claim validators, which in python-jose wrap `int(...)` in
 * `try: ... except ValueError:`) can branch on `err.name` instead of parsing
 * the message text.
 *
 * @param {string} name Python exception class name, e.g. 'ValueError'.
 * @param {string} message Python's exact message text.
 * @returns {Error}
 */
function pythonError(name, message) {
  const err = new Error(message);
  err.name = name;
  return err;
}

/**
 * Equivalent of Python's `time.time()`.
 *
 * Returns the number of seconds since the Unix epoch as a float. `Date.now()`
 * has millisecond resolution (Python's clock has microsecond resolution), which
 * is irrelevant here because the value is immediately truncated to whole
 * seconds for the `iat` claim.
 *
 * 对应 Python 的 time.time()：返回自纪元以来的浮点秒数。
 *
 * @returns {number} Float seconds since 1970-01-01T00:00:00Z (UTC).
 */
export function timeTime() {
  return Date.now() / 1000;
}

/**
 * Equivalent of Python's builtin `int()` for the value kinds this program can
 * encounter: numbers, booleans and decimal strings.
 *
 * Semantics reproduced:
 *   - floats truncate *toward zero*  (int(1.9) === 1, int(-1.9) === -1),
 *     which is `Math.trunc`, NOT `Math.floor`;
 *   - int(nan)  raises ValueError    -> Error with name 'ValueError';
 *   - int(±inf) raises OverflowError -> Error with name 'OverflowError';
 *   - int(True) === 1, int(False) === 0 (bool is a subclass of int in Python);
 *   - strings are parsed in base 10, allowing surrounding whitespace, an
 *     optional sign and PEP 515 underscore digit separators ("1_000" -> 1000);
 *     a fractional string such as "1.5" is a ValueError, exactly like Python;
 *   - anything else raises TypeError.
 *
 * 对应 Python 的 int()：向零取整，并复现 NaN / Infinity 的异常行为。
 *
 * @param {number|boolean|string} value Value to coerce.
 * @returns {number} An integral Number.
 * @throws {Error} Named 'ValueError', 'OverflowError' or 'TypeError'.
 */
export function pyInt(value) {
  // bool is an int subclass in Python: int(True) == 1.
  if (typeof value === 'boolean') {
    return value ? 1 : 0;
  }

  if (typeof value === 'number') {
    return truncateNumber(value);
  }

  if (typeof value === 'string') {
    return parseIntegerString(value);
  }

  throw pythonError(
    'TypeError',
    `int() argument must be a string, a bytes-like object or a real number, not '${pyTypeName(value)}'`,
  );
}

/**
 * Truncate a Number toward zero, rejecting the non-finite values Python
 * refuses to convert.
 *
 * @param {number} value
 * @returns {number}
 */
function truncateNumber(value) {
  if (Number.isNaN(value)) {
    throw pythonError('ValueError', NAN_ERROR_MESSAGE);
  }
  if (!Number.isFinite(value)) {
    throw pythonError('OverflowError', INFINITY_ERROR_MESSAGE);
  }
  // Math.trunc drops the fractional part without moving away from zero, and is
  // a no-op for values that are already integral (including -0 -> -0, which
  // compares equal to 0).
  return Math.trunc(value);
}

/**
 * Parse a base-10 integer literal the way Python's `int(str)` does.
 *
 * @param {string} text
 * @returns {number}
 */
function parseIntegerString(text) {
  // Python strips leading/trailing whitespace before parsing; String#trim
  // removes the same Unicode whitespace set for every character that can
  // realistically appear here.
  const trimmed = text.trim();

  // ^[+-]?  digits, optionally grouped by single underscores between digits.
  const INTEGER_LITERAL = /^[+-]?[0-9]+(?:_[0-9]+)*$/;
  if (!INTEGER_LITERAL.test(trimmed)) {
    // Python quotes the *original* (untrimmed) string in the message.
    throw pythonError('ValueError', `invalid literal for int() with base 10: '${text}'`);
  }

  const sign = trimmed[0] === '-' ? -1 : 1;
  const digits = trimmed.replace(/^[+-]/, '').replace(/_/g, '');
  return sign * Number(digits);
}

/**
 * Best-effort Python type name, used only inside TypeError messages.
 *
 * @param {unknown} value
 * @returns {string}
 */
function pyTypeName(value) {
  if (value === null || value === undefined) {
    return 'NoneType';
  }
  if (Array.isArray(value)) {
    return 'list';
  }
  if (value instanceof Map) {
    return 'dict';
  }
  return typeof value;
}

/**
 * `int(time.time())` — the current Unix timestamp in whole seconds, exactly the
 * value the reference implementation puts in the `iat` claim.
 *
 * 对应原脚本的 int(time.time())：当前纪元秒数（向零取整）。
 *
 * @returns {number} Integral seconds since the epoch.
 */
export function nowEpochSeconds() {
  return pyInt(timeTime());
}

// pytime-verify.mjs — sanity checks for /output/lib/pytime.mjs
import { timeTime, pyInt, nowEpochSeconds } from '/output/lib/pytime.mjs';

let failures = 0;
function check(label, actual, expected) {
  const ok = Object.is(actual, expected);
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${label}: got ${String(actual)} want ${String(expected)}`);
}
function checkThrows(label, fn, expectedName, expectedMessage) {
  try {
    const v = fn();
    failures++;
    console.log(`FAIL ${label}: no throw, returned ${String(v)}`);
  } catch (e) {
    const ok = e.name === expectedName && e.message === expectedMessage;
    if (!ok) failures++;
    console.log(`${ok ? 'PASS' : 'FAIL'} ${label}: ${e.name}: ${e.message}`);
  }
}

// timeTime
const t = timeTime();
check('timeTime is number', typeof t, 'number');
check('timeTime is float-ish (not forced int)', Number.isFinite(t), true);
console.log('INFO timeTime()      =', t);
console.log('INFO nowEpochSeconds =', nowEpochSeconds());
check('nowEpochSeconds integral', Number.isInteger(nowEpochSeconds()), true);
check('nowEpochSeconds == trunc(timeTime)', nowEpochSeconds(), Math.trunc(timeTime()));
check('nowEpochSeconds plausible (>2024)', nowEpochSeconds() > 1700000000, true);

// pyInt: truncation toward zero
check('pyInt(1.9)', pyInt(1.9), 1);
check('pyInt(-1.9)', pyInt(-1.9), -1);   // Python: -1, NOT -2
check('pyInt(-0.5)', pyInt(-0.5), -0);   // Math.trunc(-0.5) === -0, == 0
check('pyInt(0.0)', pyInt(0), 0);
check('pyInt(5)', pyInt(5), 5);
check('pyInt(-5)', pyInt(-5), -5);
check('pyInt(1786341745.87)', pyInt(1786341745.87), 1786341745);

// pyInt: bool
check('pyInt(true)', pyInt(true), 1);
check('pyInt(false)', pyInt(false), 0);

// pyInt: strings
check("pyInt('42')", pyInt('42'), 42);
check("pyInt('  42  ')", pyInt('  42  '), 42);
check("pyInt('+42')", pyInt('+42'), 42);
check("pyInt('-42')", pyInt('-42'), -42);
check("pyInt('1_000')", pyInt('1_000'), 1000);

// pyInt: errors
checkThrows('pyInt(NaN)', () => pyInt(NaN), 'ValueError', 'cannot convert float NaN to integer');
checkThrows('pyInt(Infinity)', () => pyInt(Infinity), 'OverflowError', 'cannot convert float infinity to integer');
checkThrows('pyInt(-Infinity)', () => pyInt(-Infinity), 'OverflowError', 'cannot convert float infinity to integer');
checkThrows("pyInt('1.5')", () => pyInt('1.5'), 'ValueError', "invalid literal for int() with base 10: '1.5'");
checkThrows("pyInt('')", () => pyInt(''), 'ValueError', "invalid literal for int() with base 10: ''");
checkThrows("pyInt('abc')", () => pyInt('abc'), 'ValueError', "invalid literal for int() with base 10: 'abc'");
checkThrows("pyInt('_1')", () => pyInt('_1'), 'ValueError', "invalid literal for int() with base 10: '_1'");
checkThrows("pyInt('1__0')", () => pyInt('1__0'), 'ValueError', "invalid literal for int() with base 10: '1__0'");
checkThrows('pyInt(null)', () => pyInt(null), 'TypeError',
  "int() argument must be a string, a bytes-like object or a real number, not 'NoneType'");
checkThrows('pyInt([])', () => pyInt([]), 'TypeError',
  "int() argument must be a string, a bytes-like object or a real number, not 'list'");
checkThrows('pyInt(new Map())', () => pyInt(new Map()), 'TypeError',
  "int() argument must be a string, a bytes-like object or a real number, not 'dict'");

// error is a real Error so `throw`/`instanceof Error` behaves normally
try { pyInt(NaN); } catch (e) { check('ValueError instanceof Error', e instanceof Error, true); }

console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURE(S)`);
process.exit(failures === 0 ? 0 : 1);
